progressive_examples.raw_code:
// Khai báo thông tin cố định của đơn hàng bằng const
const orderId = "ORD-2026-001";
const productName = "Tai nghe Bluetooth Pro";
const productUnitPrice = 1200000;

// Khai báo các thông tin có thể thay đổi bằng let
let orderQuantity = 1;
let isPaid = false;

// Tính tổng tiền thanh toán ban đầu
let initialTotal = productUnitPrice * orderQuantity;

const orderId = "ORD-2026-001";
const productName = "Tai nghe Bluetooth Pro";
const productUnitPrice = 1200000;

// Khách hàng cập nhật số lượng mua từ 1 lên 3
let orderQuantity = 1;
orderQuantity = 3;

// Trạng thái mã giảm giá (null thể hiện cố ý không có mã)
let appliedCouponCode = null;

// Biến ghi chú giao hàng chưa gán giá trị (undefined)
let deliveryNote;

// Trạng thái còn hàng trong kho
let isProductInStock = true;

// Tính tổng tiền sau khi cập nhật số lượng mới
let updatedTotal = productUnitPrice * orderQuantity;

// Hằng số cấu hình hệ thống cố định
const VAT_RATE = 0.1;
const STORE_ID = "STORE-VN-01";

// Thông tin sản phẩm và giỏ hàng
const productName = "Laptop Gaming X";
const unitPrice = 25000000;
let quantity = 2;

// Phí vận chuyển và chiết khấu
let shippingFee = 50000;
let discountAmount = 1000000;
let isVipCustomer = true;

// Thông tin bổ sung của đơn hàng
let specialInstructions = null;
let secondaryPhoneNumber;

// Tính toán các giá trị tiền tệ của đơn hàng
let subtotal = unitPrice * quantity;
let totalAfterDiscount = subtotal - discountAmount;
let taxAmount = totalAfterDiscount * VAT_RATE;
let finalAmount = totalAfterDiscount + taxAmount + shippingFee;

// Trạng thái tiến trình xử lý đơn hàng
let isOrderConfirmed = true;
let isOrderShipped = false;

